#[tokio::test]
async fn buffer_open_composite_records_nav() {
    // `record_nav_from` folds the old nav/record -> buffer/open
    // client chain into one open.
    let (_server, mut ws, origin_id) = setup_with_buffer("alpha beta\n").await;

    let opened: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            relative_path: Some("other.txt".into()),
            path_index: Some(0),
            create_if_missing: true,
            record_nav_from: Some(origin_id),
            ..Default::default()
        },
    )
    .await;
    assert_ne!(opened.buffer_id, origin_id);

    // The origin was recorded: nav/back from the new buffer returns to it.
    let back: NavStepResult = send_request::<NavStep>(
        &mut ws,
        &NavStepParams {
            buffer_id: opened.buffer_id,
            direction: Direction::Backward,
        },
    )
    .await;
    let landed = back.target.expect("nav history has the recorded origin");
    assert_eq!(landed.buffer_id, origin_id);
}

#[tokio::test]
async fn buffer_close_open_next_attaches_in_one_trip() {
    // Closing with `open_next` returns the successor fully opened —
    // the MRU buffer when one exists, a fresh scratch when none remain.
    let (_server, mut ws, first) = setup_with_buffer("one\n").await;
    let second: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            relative_path: Some("two.txt".into()),
            path_index: Some(0),
            create_if_missing: true,
            ..Default::default()
        },
    )
    .await;

    // Closing the second falls back to the first (MRU successor).
    let closed: BufferCloseResult = send_request::<BufferClose>(
        &mut ws,
        &BufferCloseParams {
            buffer_id: second.buffer_id,
            open_next: true,
        },
    )
    .await;
    let opened = closed.opened.expect("open_next returns the successor");
    assert_eq!(opened.buffer_id, first);
    assert_eq!(closed.next_buffer_id, Some(first));

    // Closing the last buffer opens a fresh scratch.
    let closed: BufferCloseResult = send_request::<BufferClose>(
        &mut ws,
        &BufferCloseParams {
            buffer_id: first,
            open_next: true,
        },
    )
    .await;
    let opened = closed
        .opened
        .expect("open_next opens a scratch when none remain");
    assert_eq!(closed.next_buffer_id, None);
    assert!(opened.path.is_none(), "fresh scratch has no path");
    assert!(opened.scratch_number.is_some());
}

#[tokio::test]
async fn workspace_activate_open_last_lands_in_one_trip() {
    // Activate + land (MRU buffer, or a fresh transient scratch on
    // first visit) in one message.
    let (_server, mut ws, buffer_id) = setup_with_buffer("hello\n").await;

    // Re-activating with open_last reattaches to the MRU buffer.
    let r: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: true,
        },
    )
    .await;
    assert_eq!(r.last_buffer_id, Some(buffer_id));
    let opened = r.opened.expect("open_last returns the landing buffer");
    assert_eq!(opened.buffer_id, buffer_id);

    // First visit (no MRU): a fresh TRANSIENT scratch.
    send_request::<BufferClose>(
        &mut ws,
        &BufferCloseParams {
            buffer_id,
            open_next: false,
        },
    )
    .await;
    let r: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: true,
        },
    )
    .await;
    assert_eq!(r.last_buffer_id, None);
    let opened = r.opened.expect("open_last opens a scratch on first visit");
    assert!(opened.path.is_none());
    assert!(
        opened.transient,
        "first-visit scratch is a transient placeholder"
    );
}

#[tokio::test]
async fn workspace_activate_lands_back_on_a_scratch_you_were_editing() {
    // Landing is kind-blind: you come back to whatever you left off in. A scratch at the front of
    // the MRU is where you were, so that is where re-activation puts you — a file behind it in the
    // MRU does *not* take precedence. (A fresh scratch is only ever minted when there is nothing to
    // return to at all, which is a state with no file to prefer either.)
    let (_server, mut ws, file_id) = setup_with_buffer("hello\n").await;

    // Open a scratch *after* the file, putting it at the front of the MRU.
    let scratch: BufferOpenResult = send_request::<BufferOpen>(
        &mut ws,
        &BufferOpenParams {
            transient: None,
            buffer_id: None,
            ..Default::default()
        },
    )
    .await;
    assert!(scratch.path.is_none(), "opened a scratch");
    assert_ne!(scratch.buffer_id, file_id);

    let r: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: true,
        },
    )
    .await;
    assert_eq!(
        r.last_buffer_id,
        Some(scratch.buffer_id),
        "the scratch you were last in wins over the file behind it"
    );
    let opened = r.opened.expect("open_last returns the landing buffer");
    assert_eq!(opened.buffer_id, scratch.buffer_id);

    // Closing it falls back to the file rather than minting a second scratch.
    send_request::<BufferClose>(
        &mut ws,
        &BufferCloseParams {
            buffer_id: scratch.buffer_id,
            open_next: false,
        },
    )
    .await;
    let r: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: true,
        },
    )
    .await;
    assert_eq!(
        r.last_buffer_id,
        Some(file_id),
        "with the scratch gone, the file is the landing target"
    );
}

#[tokio::test]
async fn input_text_at_selection_start_inserts_before() {
    // Paste-before's collapse rides the edit itself.
    let (_server, mut ws, buffer_id) = setup_with_buffer("abcde\n").await;
    // Select "bcd" (cursor on 'd', anchor on 'b').
    send_request::<CursorSet>(
        &mut ws,
        &CursorSetParams {
            granularity: Granularity::Char,
            buffer_id,
            position: LogicalPosition { line: 0, col: 3 },
            anchor: LogicalPosition { line: 0, col: 1 },
        },
    )
    .await;
    let r: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id,
            text: "XY".into(),
            select_pasted: true,
            replace_selection: false,
            at: Some(SelectionEdge::Start),
        },
    )
    .await;
    // Inserted BEFORE 'b' — nothing replaced — with the pasted text selected.
    assert_eq!(buffer_text(&mut ws, buffer_id).await, "aXYbcde\n");
    assert_eq!(r.cursor.anchor, LogicalPosition { line: 0, col: 1 });
    assert_eq!(r.cursor.position, LogicalPosition { line: 0, col: 2 });
}

