// ---- cursor/tree_select ---------------------------------------------------------------------

/// A function with one nested statement, so the expand chain has several distinct rungs.
const TREE_SRC: &str = "fn main() {\n    let x = 42;\n}\n";

/// The text a cursor covers, given `TREE_SRC`. Selections are inclusive on both endpoints, so the
/// cursor's own character is part of the range. Asserting on the *text* rather than on node kinds
/// keeps these tests readable and stops a grammar rename from failing them for the wrong reason.
fn tree_selected(cur: &CursorState) -> String {
    let lines: Vec<&str> = TREE_SRC.split('\n').collect();
    let flat = |p: LogicalPosition| -> usize {
        lines[..p.line as usize]
            .iter()
            .map(|l| l.len() + 1)
            .sum::<usize>()
            + p.col as usize
    };
    let (a, b) = (flat(cur.anchor), flat(cur.position));
    let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
    TREE_SRC[lo..(hi + 1).min(TREE_SRC.len())].to_string()
}

/// Open `TREE_SRC` as Rust and park the cursor inside the `42` literal.
async fn tree_setup() -> (aether_server::ServerHandle, Ws, u64) {
    let (server, mut ws, open) = setup_with_named_file("a.rs", TREE_SRC).await;
    let pos = LogicalPosition { line: 1, col: 12 }; // the `4` of `42`
    let _: CursorState = send_request::<CursorSet>(
        &mut ws,
        &CursorSetParams {
            granularity: Granularity::Char,
            buffer_id: open.buffer_id,
            position: pos,
            anchor: pos,
        },
    )
    .await;
    (server, ws, open.buffer_id)
}

async fn tree_select(ws: &mut Ws, buffer_id: u64, dir: TreeSelectDirection, count: u32) -> String {
    let c: CursorState = send_request::<CursorTreeSelect>(
        ws,
        &CursorTreeSelectParams {
            buffer_id,
            direction: dir,
            count,
        },
    )
    .await;
    tree_selected(&c)
}

/// Each expand grows to the smallest syntax node strictly larger than the current selection: the
/// literal, its statement, the block, the function, the file.
#[tokio::test]
async fn tree_select_expand_climbs_to_each_enclosing_node() {
    let (server, mut ws, b) = tree_setup().await;
    let mut chain = Vec::new();
    for _ in 0..5 {
        chain.push(tree_select(&mut ws, b, TreeSelectDirection::Expand, 1).await);
    }
    assert_eq!(
        chain,
        vec![
            "42".to_string(),
            "let x = 42;".to_string(),
            "{\n    let x = 42;\n}".to_string(),
            "fn main() {\n    let x = 42;\n}".to_string(),
            TREE_SRC.to_string(),
        ]
    );
    drop(server);
}

/// Past the root there is nothing larger to select, so the press is a no-op rather than an error —
/// holding the key down must settle rather than thrash or fail.
#[tokio::test]
async fn tree_select_expand_is_a_stable_no_op_at_the_root() {
    let (server, mut ws, b) = tree_setup().await;
    for _ in 0..5 {
        tree_select(&mut ws, b, TreeSelectDirection::Expand, 1).await;
    }
    let at_root = tree_select(&mut ws, b, TreeSelectDirection::Expand, 1).await;
    assert_eq!(at_root, TREE_SRC, "already covering the whole file");
    for _ in 0..3 {
        assert_eq!(
            tree_select(&mut ws, b, TreeSelectDirection::Expand, 1).await,
            at_root,
            "further expands at the root must not move the selection"
        );
    }
    drop(server);
}

/// Contract walks back down the history one rung per press, and stops — it does not fall through
/// to some smaller node it never came from.
#[tokio::test]
async fn tree_select_contract_retraces_the_chain_then_stops() {
    let (server, mut ws, b) = tree_setup().await;
    for _ in 0..3 {
        tree_select(&mut ws, b, TreeSelectDirection::Expand, 1).await;
    }
    assert_eq!(
        tree_select(&mut ws, b, TreeSelectDirection::Contract, 1).await,
        "let x = 42;"
    );
    assert_eq!(
        tree_select(&mut ws, b, TreeSelectDirection::Contract, 1).await,
        "42"
    );
    // Back where we started: the collapsed cursor on the `4`.
    let start = tree_select(&mut ws, b, TreeSelectDirection::Contract, 1).await;
    assert_eq!(start, "4");
    assert_eq!(
        tree_select(&mut ws, b, TreeSelectDirection::Contract, 1).await,
        start,
        "an exhausted history leaves the cursor where it is"
    );
    drop(server);
}

/// `count` runs the repeat server-side, so one round trip equals N presses.
#[tokio::test]
async fn tree_select_count_repeats_server_side() {
    let (server, mut ws, b) = tree_setup().await;
    let in_one = tree_select(&mut ws, b, TreeSelectDirection::Expand, 3).await;

    let (server2, mut ws2, b2) = tree_setup().await;
    let mut stepwise = String::new();
    for _ in 0..3 {
        stepwise = tree_select(&mut ws2, b2, TreeSelectDirection::Expand, 1).await;
    }
    assert_eq!(in_one, stepwise, "count 3 == three separate presses");
    assert_eq!(in_one, "{\n    let x = 42;\n}");
    drop(server);
    drop(server2);
}

/// A buffer with no grammar has no tree to climb; the cursor is returned untouched rather than the
/// request failing.
#[tokio::test]
async fn tree_select_without_syntax_leaves_the_cursor_alone() {
    let (server, mut ws, buffer_id) = setup_with_buffer("hello world\n").await;
    let pos = LogicalPosition { line: 0, col: 3 };
    let before: CursorState = send_request::<CursorSet>(
        &mut ws,
        &CursorSetParams {
            granularity: Granularity::Char,
            buffer_id,
            position: pos,
            anchor: pos,
        },
    )
    .await;
    let after: CursorState = send_request::<CursorTreeSelect>(
        &mut ws,
        &CursorTreeSelectParams {
            buffer_id,
            direction: TreeSelectDirection::Expand,
            count: 1,
        },
    )
    .await;
    assert_eq!(after.position, before.position);
    assert_eq!(after.anchor, before.anchor);
    drop(server);
}

/// Moving the cursor by any other means abandons the expand chain: a later contract must not
/// resurrect a selection from before the move. The clearing is an explicit call in each cursor
/// handler rather than something the type system enforces, which is exactly why it is pinned here.
#[tokio::test]
async fn a_plain_motion_clears_the_expand_history() {
    let (server, mut ws, b) = tree_setup().await;
    tree_select(&mut ws, b, TreeSelectDirection::Expand, 1).await;
    tree_select(&mut ws, b, TreeSelectDirection::Expand, 1).await;

    let moved: CursorState = send_request::<CursorMove>(
        &mut ws,
        &CursorMoveParams {
            buffer_id: b,
            motion: Motion::Char {
                direction: Direction::Forward,
                count: 1,
            },
            extend_selection: false,
        },
    )
    .await;
    let after_move = tree_selected(&moved);

    assert_eq!(
        tree_select(&mut ws, b, TreeSelectDirection::Contract, 1).await,
        after_move,
        "contract after an unrelated motion must not restore the pre-move selection"
    );
    drop(server);
}
